def solve(x,wq,wk,wv,wo,heads):
    x=np.asarray(x);b,t,d=x.shape;h=heads;dh=d//h
    def split(w):return (x@np.asarray(w)).reshape(b,t,h,dh).transpose(0,2,1,3)
    q,k,v=map(split,(wq,wk,wv));s=q@k.swapaxes(-1,-2)/np.sqrt(dh)
