import numpy as np
def solve(tokens):
    return [tokens[:-1],tokens[1:]]

import torch
import torch.nn.functional as F


def shifted(window):
    return window[:, :-1], window[:, 1:]


def embed(ids, p):
    return p["token"][ids] + p["position"][:ids.shape[1]]


def attention(n, p):
    batch, time, width = n.shape
    def heads(w):
        return (n @ w).reshape(batch, time, 2, width // 2).transpose(1, 2)
    q, k, v = [heads(p[name]) for name in ("q", "k", "v")]
    scores = q @ k.transpose(-1, -2) / (width // 2) ** 0.5
    allowed = torch.ones(time, time, dtype=torch.bool).tril()
    mixed = scores.masked_fill(~allowed, -torch.inf).softmax(-1) @ v
    return mixed.transpose(1, 2).reshape(batch, time, width) @ p["out"]


def block(x, p):
    width = x.size(-1)
    n = F.layer_norm(x, (width,))
    h = x + attention(n, p)
    z = F.layer_norm(h, (width,))
    return h + F.relu(z @ p["up"]) @ p["down"]


def logits(x, p):
    return block(x, p) @ p["lm"]
